  <div class="container">
    <div class="row v-m-10">
      <div class="col-sm-5 col-md-5 col-lg-5 display-flex align-items-center">
        <span>{{ $t('group_main_setting') }}</span>
        <f-toggle
          class="ml-10"
          size="xs"
          v-model="user_settings['GROUP_PERMISSION_ACTIVATED']"
          @update:model-value="
            (val: any) => {
              saveSetting('GROUP_PERMISSION_ACTIVATED', val);
            }
          "
        />
      </div>
      <div class="col-sm-7 col-md-7 col-lg-7"></div>
    </div>
    <div class="row mt-10 mb-25 justify-between">
      <div class="col-sm-6 col-md-6 col-lg-6">
        <q-input
          v-model="searchBy"
          dense
          :class="searchBy.length === 0 ? 'search-in-active' : 'search-active'"
          autofocus
          :placeholder="$t('search_group')"
          outlined
          @update:model-value="updateDebouncedSearch"
        >
          <template v-slot:append>
            <q-icon
              flat
              dense
              class="cursor-pointer"
              name="search"
              size="24px"
              color="primary"
            />
          </template>
        </q-input>
      </div>
      <div class="row q-gutter-sm">
        <f-btn
          icon="add"
          :label="$t('new')"
          @click="display_create_group_dialog = true"
        />
      </div>
    </div>
    <div class="full-width" v-if="user_settings['GROUP_PERMISSION_ACTIVATED']">
      <DocBitsTable
        :rows="filteredGroups"
        :columns="columns"
        row-key="group_id"
        table-id="groups_table"
        :loading="processing"
        :features="{
          sorting: true,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          clientSideSort: true,
          columnReorder: true,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
        }"
        :row-actions="rowActions"
        :column-order="columnOrder"
        :pagination="sortState"
        no-data-label="no_record_found"
        table-class="temp-table-height"
        flat-style
        @update:sorting="handleSort"
        @row-action="handleRowAction"
        @column-reorder="handleColumnReorder"
      >
        <!-- Group name column -->
        <template #body-cell-group_name="{ row }">
          {{ row.group_name }}
        </template>

        <!-- Description column -->
        <template #body-cell-description="{ row }">
          {{ row.description || '-' }}
        </template>
      </DocBitsTable>
    </div>
  </div>
  <q-dialog
    v-model="permission_form"
    persistent
    @keydown.esc="permission_form = false"
  >
    <CreateGroup
      :is_edit="true"
      :name="group_edit_name"
      :id="group_edit_id"
    ></CreateGroup>
  </q-dialog>
  <q-dialog v-model="deleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
        />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteGroup()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="display_create_group_dialog"
    persistent
    @keydown.esc="display_create_group_dialog = false"
  >
    <CreateGroup></CreateGroup>
  </q-dialog>

  <q-dialog
    v-model="display_users_dialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="display_users_dialog = false"
  >
    <q-card style="width: 700px; max-width: 1060px; height: 600px">
      <q-toolbar class="secondary-toolbar text-white">
        <q-toolbar-title>
          <span class="text-weight-bold"
            >{{ selectedGroupName }} {{ $t('users') }}</span
          >
        </q-toolbar-title>

        <f-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>
      <q-card-section class="row items-center q-pb-none"> </q-card-section>

      <q-card-section>
        <div
          class="table-container col-sm-12 col-md-12 col-lg-12 min-height-300"
        >
          <ManageUser :groupId="selectedGroupId" />
        </div>
      </q-card-section>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { debounce } from 'quasar';
import ManageUser from './ManageUser.vue';
import { Acl } from 'src/core/acls/index';
import { defineComponent, ref, computed, reactive } from 'vue';
import CreateGroup from './CreateGroup.vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import cache from 'src/utils/cache';
import { CONSTANTS } from 'src/constants';
import { useDocPermissionsStore, useSettingStore } from 'src/store/main';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  SortEventPayload,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  el: '#app',
  mixins: [cache],
  components: {
    ManageUser,
    CreateGroup,
    DocBitsTable,
  },
  data() {
    return {
      dialog: false,
      permission_form: ref(false),
      group_edit_name: ref(''),
      group_edit_id: ref(''),
      searchBy: '',
      debouncedSearch: '',
      debounceSearchFunc: null as any,
    };
  },
  computed: {
    filteredGroups(): any[] {
      const query = this.debouncedSearch.trim().toLowerCase();
      if (!query) return this.groups;
      return this.groups.filter(
        (g: any) =>
          g.group_name?.toLowerCase().includes(query) ||
          g.description?.toLowerCase().includes(query),
      );
    },
  },
  mounted() {
    this.initView();
    this.debounceSearchFunc = debounce((val: string) => {
      this.debouncedSearch = val;
    }, 500);
    document.addEventListener('group_added', this.groupAdded);
    document.addEventListener('group_edited', this.groupEdited);
  },
  unmounted() {
    document.removeEventListener('group_added', this.groupAdded);
    document.removeEventListener('group_edited', this.groupEdited);
  },
  methods: {
    async initView() {
      try {
        this.processing = true;
        this.setSettings();
        this.loadColumnOrder();
        this.loadSavedSort();
        await this.getList();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    updateDebouncedSearch(val: any) {
      this.searchBy = val;
      this.debounceSearchFunc(val);
    },
    loadColumnOrder() {
      const savedOrderString = this.getDataByKey(CONSTANTS.groups_columns_order);
      if (savedOrderString) {
        this.columnOrder = JSON.parse(savedOrderString as string);
      }
    },
    openForm(row: any) {
      if (row) {
        this.group_edit_name = row.group_name;
        this.group_edit_id = row.group_id;
      }
      this.permission_form = true;
    },
    async saveSetting(key: string, value: any) {
      try {
        this.processing = true;
        await this.updateSetting(key, value);
        this.setSettings();
        await Acl.refresh(); // Force refresh after permissions change
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    setSettings() {
      if (!this.user_settings['GROUP_PERMISSION_ACTIVATED']) {
        this.user_settings['GROUP_PERMISSION_ACTIVATED'] = false;
      }
    },

    groupAdded() {
      this.display_create_group_dialog = false;
      // Store already pushed to list - no re-fetch needed
    },
    groupEdited() {
      this.permission_form = false;
      // Store already updated in list - no re-fetch needed
    },

    async deleteGroup() {
      try {
        if (!this.delete_id) {
          return;
        }
        this.processing = true;
        // Use store method which handles API call + list removal
        await this.deleteGroupById(this.delete_id);
        this.delete_id = '';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    viewAccessControl(row: any) {
      const group_name = row.group_name as string;
      const group_id = row.group_id as string;
      this.$router.push(`/settings/access-control/${group_name}/${group_id}`);
    },
    manageUsers(row: any) {
      this.selectedGroupId = row.group_id;
      this.selectedGroupName = row.group_name;
      this.display_users_dialog = true;
    },

    async getList() {
      try {
        this.processing = true;
        await this.getPermissionsData();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    loadSavedSort() {
      const savedSortStr = this.getDataByKey(CONSTANTS.groups_sort_order);
      if (savedSortStr) {
        try {
          const savedSort = JSON.parse(savedSortStr as string);
          this.sortState.sortBy = savedSort.sort_by;
          this.sortState.descending = savedSort.sort_order === 'desc';
        } catch {
          // Ignore parse errors
        }
      }
    },

    persistSort(sortBy: string, direction: string) {
      const sortOrder = {
        sort_by: sortBy,
        sort_order: direction,
      };
      this.setDataToLocalStorage(CONSTANTS.groups_sort_order, JSON.stringify(sortOrder));
    },

    handleSort(payload: SortEventPayload) {
      this.sortState.sortBy = payload.column;
      this.sortState.descending = payload.direction === 'desc';
      this.persistSort(payload.column, payload.direction);
    },
    handleRowAction(payload: RowActionPayload) {
      if (payload.action === 'manage-users') {
        this.manageUsers(payload.row);
      } else if (payload.action === 'view-access-control') {
        this.viewAccessControl(payload.row);
      } else if (payload.action === 'edit') {
        this.openForm(payload.row);
      } else if (payload.action === 'delete') {
        this.delete_id = payload.rowId;
        this.deleteConfirm = true;
      }
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(
        CONSTANTS.groups_columns_order,
        JSON.stringify(newOrder),
      );
    },
  },
  setup() {
    const { t } = useTranslate();
    const permission_store = useDocPermissionsStore();
    const { processing, groups } = storeToRefs(permission_store);
    const { getPermissionsData, deleteGroupById } = permission_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    // Sort state for client-side sorting
    const sortState = reactive({
      sortBy: 'group_name' as string | null,
      descending: false,
    });

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'group_name',
        label: t.value('group_name'),
        field: 'group_name',
        sortable: true,
        align: 'left',
      },
      {
        name: 'description',
        label: t.value('group_description'),
        field: 'description',
        sortable: true,
        align: 'left',
      },
    ]);

    // Row actions - conditionally include access control based on setting
    const rowActions = computed<RowActionItem[]>(() => {
      const actions: RowActionItem[] = [
        {
          key: 'manage-users',
          label: 'manage_users',
          icon: 'people',
          color: 'primary',
        },
        {
          key: 'view-access-control',
          label: 'view_access_control',
          icon: 'admin_panel_settings',
          color: 'grey-7',
        },
        {
          key: 'edit',
          label: 'edit',
          icon: 'edit',
          color: 'grey-7',
        },
        {
          key: 'delete',
          label: 'delete',
          icon: 'delete',
          color: 'negative',
          separator: true,
        },
      ];

      return actions;
    });

    return {
      processing,
      groups,
      getPermissionsData,
      deleteGroupById,
      updateSetting,
      display_users_dialog: ref(false),
      display_create_group_dialog: ref(false),
      columns,
      rowActions,
      columnOrder: ref<string[]>([]),
      sortState,
      selectedGroupId: ref(''),
      selectedGroupName: ref(''),
      deleteConfirm: ref(false),
      delete_id: ref(''),
      user_settings,
      t,
    };
  },
});
</script>
